90	/// Minimal, strict DER decoder and the slice of X.509 needed by `inspect`.
91	mod x509 {
92	    use std::fmt::Write;
93	
94	    pub(super) struct Cert {
95	        pub(super) subject: String,
96	        pub(super) issuer: String,
97	        pub(super) serial_hex: String,
98	        pub(super) not_before: String,
99	        pub(super) not_after: String,
100	    }
101	
102	    #[derive(Clone, Copy)]
103	    struct Tlv<'a> {
104	        tag: u8,
105	        content: &'a [u8],
106	    }
107	
108	    const TAG_INTEGER: u8 = 0x02;
109	    const TAG_BIT_STRING: u8 = 0x03;
110	    const TAG_OID: u8 = 0x06;
111	    const TAG_SEQUENCE: u8 = 0x30;
112	    const TAG_SET: u8 = 0x31;
113	    const TAG_UTC_TIME: u8 = 0x17;
114	    const TAG_GENERALIZED_TIME: u8 = 0x18;
115	
116	    /// Read exactly one DER TLV. Rejects indefinite length, non-minimal
117	    /// length encodings and truncated data.
118	    fn read_tlv(buf: &[u8]) -> Result<(Tlv<'_>, &[u8]), String> {
119	        let tag = *buf.first().ok_or_else(|| "unexpected end of data".to_string())?;
120	        if tag & 0x1F == 0x1F {
121	            return Err("multi-byte tags are not supported".to_string());
122	        }
123	        let first_len = *buf.get(1).ok_or_else(|| "truncated length".to_string())?;
124	        let (len, header_len) = match first_len {
125	            0x00..=0x7F => (first_len as usize, 2),
126	            0x80 => return Err("indefinite length is not valid DER".to_string()),
127	            0xFF => return Err("reserved length byte".to_string()),
128	            long => {
129	                let n = (long & 0x7F) as usize;
130	                if !(1..=4).contains(&n) {
131	                    return Err("length is too large".to_string());
132	                }
133	                let bytes = buf
134	                    .get(2..2 + n)
135	                    .ok_or_else(|| "truncated long length".to_string())?;
136	                if bytes[0] == 0 {
137	                    return Err("non-minimal length encoding".to_string());
138	                }
139	                let mut len = 0usize;
140	                for &b in bytes {
141	                    len = len
142	                        .checked_shl(8)
143	                        .and_then(|l| l.checked_add(b as usize))
144	                        .ok_or_else(|| "length overflow".to_string())?;
145	                }
146	                if len < 0x80 {
147	                    return Err("non-minimal length encoding".to_string());
148	                }
149	                (len, 2 + n)
150	            }
151	        };
152	        let total = header_len
153	            .checked_add(len)
154	            .filter(|&t| t <= buf.len())
155	            .ok_or_else(|| "truncated TLV content".to_string())?;
156	        Ok((
157	            Tlv {
158	                tag,
159	                content: &buf[header_len..total],
160	            },
161	            &buf[total..],
162	        ))
163	    }
164	
165	    fn read_tagged<'a>(
166	        buf: &'a [u8],
167	        tag: u8,
168	        what: &str,
169	    ) -> Result<(Tlv<'a>, &'a [u8]), String> {
170	        let (tlv, rest) = read_tlv(buf).map_err(|e| format!("{what}: {e}"))?;
171	        if tlv.tag != tag {
172	            return Err(format!("expected {what} (tag 0x{tag:02X}), got 0x{:02X}", tlv.tag));
173	        }
174	        Ok((tlv, rest))
175	    }
176	
177	    pub(super) fn parse(bytes: &[u8]) -> Result<Cert, String> {
178	        // Certificate ::= SEQUENCE { tbsCertificate, signatureAlgorithm,
179	        // signatureValue BIT STRING } — and nothing trailing.
180	        let (cert, rest) = read_tagged(bytes, TAG_SEQUENCE, "Certificate SEQUENCE")?;
181	        if !rest.is_empty() {
182	            return Err(format!("{} trailing byte(s) after certificate", rest.len()));
183	        }
184	
185	        let c = cert.content;
186	        let (tbs, c) = read_tagged(c, TAG_SEQUENCE, "tbsCertificate")?;
187	        let (_sig_alg, c) = read_tagged(c, TAG_SEQUENCE, "signatureAlgorithm")?;
188	        let (sig_value, c) = read_tlv(c)?;
189	        if sig_value.tag != TAG_BIT_STRING {
190	            return Err("signature must be a BIT STRING".to_string());
191	        }
192	        if sig_value.content.is_empty() || sig_value.content[0] > 7 {
193	            return Err("invalid signature BIT STRING".to_string());
194	        }
195	        if !c.is_empty() {
196	            return Err("trailing data in Certificate".to_string());
197	        }
198	
199	        // TBSCertificate ::= SEQUENCE {
200	        //   version [0] EXPLICIT Version DEFAULT v1, serialNumber, signature,
201	        //   issuer, validity, subject, subjectPublicKeyInfo, ... }
202	        let t = tbs.content;
203	        let (first, t2) = read_tlv(t)?;
204	        let t = if first.tag == 0xA0 {
205	            let (version, vrest) = read_tagged(first.content, TAG_INTEGER, "version")?;
206	            if !vrest.is_empty() || version.content.len() != 1 || version.content[0] > 2 {
207	                return Err("invalid certificate version".to_string());
208	            }
209	            t2
210	        } else {
211	            t // No explicit version: v1 certificate.
212	        };
213	
214	        let (serial, t3) = read_tagged(t, TAG_INTEGER, "serialNumber")?;
215	        let t = t3;
216	        let (_tbs_sig, t) = read_tagged(t, TAG_SEQUENCE, "tbs signatureAlgorithm")?;
217	        let (issuer, t) = read_tagged(t, TAG_SEQUENCE, "issuer")?;
218	        let (validity, t) = read_tagged(t, TAG_SEQUENCE, "validity")?;
219	        let (subject, t) = read_tagged(t, TAG_SEQUENCE, "subject")?;
220	        let (spki, mut t) = read_tagged(t, TAG_SEQUENCE, "subjectPublicKeyInfo")?;
221	        check_spki(spki)?;
222	        // Remaining fields (issuerUniqueID, subjectUniqueID, extensions, ...)
223	        // are optional; they must still each be well-formed TLVs.
224	        while !t.is_empty() {
225	            let (_, rest) = read_tlv(t)?;
226	            t = rest;
227	        }
228	
229	        let serial_hex = format_serial(serial.content)?;
230	        let issuer = format_name(issuer)?;
231	        let subject = format_name(subject)?;
232	
233	        let v = validity.content;
234	        let (nb, v2) = read_tlv(v)?;
235	        let (na, v3) = read_tlv(v2)?;
236	        if !v3.is_empty() {
237	            return Err("trailing data in validity".to_string());
238	        }
239	        let not_before = format_time(nb)?;
240	        let not_after = format_time(na)?;
241	
242	        Ok(Cert {
243	            subject,
244	            issuer,
245	            serial_hex,
246	            not_before,
247	            not_after,
248	        })
249	    }
250	
251	    /// SubjectPublicKeyInfo ::= SEQUENCE {
252	    ///   algorithm        AlgorithmIdentifier,
253	    ///   subjectPublicKey BIT STRING }
254	    /// Nothing may be missing and no extra elements may follow.
255	    fn check_spki(spki: Tlv) -> Result<(), String> {
256	        let (alg, rest) = read_tagged(
257	            spki.content,
258	            TAG_SEQUENCE,
259	            "subjectPublicKeyInfo algorithm identifier",
260	        )?;
261	        check_algorithm_identifier(alg)?;
262	        let (key, rest) = read_tagged(rest, TAG_BIT_STRING, "subjectPublicKey")?;
263	        check_bit_string(key.content, "subjectPublicKey")?;
264	        if !rest.is_empty() {
265	            return Err("trailing data in subjectPublicKeyInfo".to_string());
266	        }
267	        Ok(())
268	    }
269	
270	    /// AlgorithmIdentifier ::= SEQUENCE {
271	    ///   algorithm  OBJECT IDENTIFIER,
272	    ///   parameters ANY DEFINED BY algorithm OPTIONAL }
273	    /// The parameters, if present, must be exactly one complete DER TLV;
274	    /// absent parameters and an explicit NULL are both accepted. The
275	    /// parameter content is not interpreted for any particular algorithm.
276	    fn check_algorithm_identifier(alg: Tlv) -> Result<(), String> {
277	        let (oid, rest) = read_tagged(alg.content, TAG_OID, "algorithm OID")?;
278	        parse_oid(oid.content).map_err(|e| format!("algorithm OID: {e}"))?;
279	        if rest.is_empty() {
280	            return Ok(());
281	        }
282	        let (_params, after) =
283	            read_tlv(rest).map_err(|e| format!("algorithm parameters: {e}"))?;
284	        if !after.is_empty() {
285	            return Err("multiple algorithm parameters".to_string());
286	        }
287	        Ok(())
288	    }
289	
290	    /// Validate the DER content of a BIT STRING: one leading byte counting
291	    /// unused bits (0..=7), and when the count is nonzero those low bits of
292	    /// the final data byte must all be zero. An empty bit string is only
293	    /// legal with a zero count.
294	    fn check_bit_string(content: &[u8], what: &str) -> Result<(), String> {
295	        let unused = *content
296	            .first()
297	            .ok_or_else(|| format!("{what} BIT STRING is missing the unused-bits byte"))?;
298	        if unused > 7 {
299	            return Err(format!("{what} BIT STRING has invalid unused-bits count {unused}"));
300	        }
301	        let data = &content[1..];
302	        if data.is_empty() {
303	            if unused != 0 {
304	                return Err(format!(
305	                    "{what} BIT STRING declares {unused} unused bits but has no data"
306	                ));
307	            }
308	            return Ok(());
309	        }
310	        if unused != 0 && data[data.len() - 1] & ((1u8 << unused) - 1) != 0 {
311	            return Err(format!(
312	                "{what} BIT STRING has set bits among the {unused} unused trailing bits"
313	            ));
314	        }
315	        Ok(())
316	    }
317	
318	    /// Render the serial number as upper-case hex, matching the integer value
319	    /// (a DER sign-padding 0x00 byte is not part of the number).
320	    fn format_serial(content: &[u8]) -> Result<String, String> {
321	        if content.is_empty() {
322	            return Err("empty serial number".to_string());
323	        }
324	        if content.len() > 1 && content[0] == 0xFF && content[1] & 0x80 == 0 {
325	            return Err("non-minimal serial number encoding".to_string());
326	        }
327	        if content.len() > 1 && content[0] == 0x00 && content[1] & 0x80 == 0 {
328	            return Err("non-minimal serial number encoding".to_string());
329	        }
330	        if content[0] & 0x80 != 0 && !(content.len() > 1 && content[0] == 0x00) {
331	            return Err("negative serial number".to_string());
332	        }
333	        let digits = if content.len() > 1 && content[0] == 0x00 {
334	            &content[1..]
335	        } else {
336	            content
337	        };
338	        let mut s = String::with_capacity(digits.len() * 2);
339	        for b in digits {
340	            write!(s, "{b:02X}").unwrap();
341	        }
342	        if s.is_empty() {
343	            s.push_str("00");
344	        }
345	        Ok(s)
346	    }
347	
348	    /// Name ::= SEQUENCE OF RDN; rendered per RFC 4514 (RDNs reversed,
349	    /// multi-valued RDNs joined with '+'). Values of known attribute types
350	    /// are emitted as real UTF-8 text so non-ASCII content is preserved
351	    /// verbatim; attributes without a known short name use their dotted OID
352	    /// and the '#' form carrying the value's full DER encoding in hex.
353	    fn format_name(name: Tlv) -> Result<String, String> {
354	        let mut rdn_buf = name.content;
355	        let mut rdns: Vec<String> = Vec::new();
356	        while !rdn_buf.is_empty() {
357	            let (set, rest) = read_tagged(rdn_buf, TAG_SET, "RelativeDistinguishedName")?;
358	            rdn_buf = rest;
359	
360	            let mut atv_buf = set.content;
361	            let mut parts = Vec::new();
362	            while !atv_buf.is_empty() {
363	                let (atv, rest) =
364	                    read_tagged(atv_buf, TAG_SEQUENCE, "AttributeTypeAndValue")?;
365	                atv_buf = rest;
366	
367	                let (oid, after_oid) = read_tagged(atv.content, TAG_OID, "attribute OID")?;
368	                let (value, after_value) = read_tlv(after_oid)?;
369	                if !after_value.is_empty() {
370	                    return Err("trailing data in attribute value".to_string());
371	                }
372	
373	                let oid_arcs = parse_oid(oid.content)?;
374	                match oid_short_name(&oid_arcs) {
375	                    Some(label) => {
376	                        let text = decode_attribute_value(value.tag, value.content)?;
377	                        parts.push(format!("{label}={}", escape_value(&text)));
378	                    }
379	                    None => {
380	                        // Unknown attribute type: RFC 4514 requires the form
381	                        // OID=#hex, where the hex is the full DER encoding
382	                        // (tag, length and content) of the attribute value.
383	                        // The value is still validated: a UTF8String must
384	                        // hold valid UTF-8 even when shown as hex.
385	                        if value.tag == 0x0C {
386	                            std::str::from_utf8(value.content)
387	                                .map_err(|_| "invalid UTF-8 in UTF8String".to_string())?;
388	                        }
389	                        let tlv_len = after_oid.len() - after_value.len();
390	                        let tlv_bytes = &after_oid[..tlv_len];
391	                        let mut hex = String::with_capacity(tlv_bytes.len() * 2);
392	                        for b in tlv_bytes {
393	                            write!(hex, "{b:02X}").unwrap();
394	                        }
395	                        parts.push(format!("{}=#{hex}", arcs_to_string(&oid_arcs)));
396	                    }
397	                }
398	            }
399	            if parts.is_empty() {
400	                return Err("empty RelativeDistinguishedName".to_string());
401	            }
402	            rdns.push(parts.join("+"));
403	        }
404	        rdns.reverse();
405	        Ok(rdns.join(","))
406	    }
407	
408	    fn parse_oid(content: &[u8]) -> Result<Vec<u64>, String> {
409	        if content.is_empty() {
410	            return Err("empty OID".to_string());
411	        }
412	        let mut arcs = Vec::new();
413	        // The first subidentifier encodes the first two arcs as
414	        // 40*first + second and is itself a base-128 quantity, so it can
415	        // span multiple content bytes (e.g. 2.999 encodes as 0x88 0x37).
416	        let mut i = 0;
417	        let first = read_oid_arc(content, &mut i)?;
418	        match first {
419	            0..=39 => {
420	                arcs.push(0);
421	                arcs.push(first);
422	            }
423	            40..=79 => {
424	                arcs.push(1);
425	                arcs.push(first - 40);
426	            }
427	            _ => {
428	                arcs.push(2);
429	                arcs.push(first - 80);
430	            }
431	        }
432	        while i < content.len() {
433	            arcs.push(read_oid_arc(content, &mut i)?);
434	        }
435	        Ok(arcs)
436	    }
437	
438	    /// Read one base-128 subidentifier starting at `*i`. Rejects trailing
439	    /// continuation bytes and non-minimal encodings.
440	    fn read_oid_arc(content: &[u8], i: &mut usize) -> Result<u64, String> {
441	        let start = *i;
442	        let mut value = 0u64;
443	        loop {
444	            let b = *content
445	                .get(*i)
446	                .ok_or_else(|| "truncated OID arc".to_string())?;
447	            value = value
448	                .checked_mul(128)
449	                .and_then(|v| v.checked_add((b & 0x7F) as u64))
450	                .ok_or_else(|| "OID arc overflow".to_string())?;
451	            *i += 1;
452	            if b & 0x80 == 0 {
453	                break;
454	            }
455	        }
456	        if *i - start > 1 && content[start] == 0x80 {
457	            return Err("non-minimal OID arc encoding".to_string());
458	        }
459	        Ok(value)
460	    }
461	
462	    fn arcs_to_string(arcs: &[u64]) -> String {
463	        arcs.iter()
464	            .map(u64::to_string)
465	            .collect::<Vec<_>>()
466	            .join(".")
467	    }
468	
469	    fn oid_short_name(arcs: &[u64]) -> Option<&'static str> {
470	        // X.520 / X.521 (2.5.4.*) and the commonly used LDAP/PKCS names.
471	        let name = match arcs {
472	            [2, 5, 4, 3] => "CN",
473	            [2, 5, 4, 4] => "SN",
474	            [2, 5, 4, 5] => "serialNumber",
475	            [2, 5, 4, 6] => "C",
476	            [2, 5, 4, 7] => "L",
477	            [2, 5, 4, 8] => "ST",
478	            [2, 5, 4, 9] => "STREET",
479	            [2, 5, 4, 10] => "O",
480	            [2, 5, 4, 11] => "OU",
481	            [2, 5, 4, 12] => "title",
482	            [2, 5, 4, 17] => "postalAddress",
483	            [2, 5, 4, 18] => "postalCode",
484	            [2, 5, 4, 20] => "telephoneNumber",
485	            [2, 5, 4, 42] => "givenName",
486	            [2, 5, 4, 43] => "initials",
487	            [2, 5, 4, 44] => "generationQualifier",
488	            [2, 5, 4, 46] => "dnQualifier",
489	            [2, 5, 4, 65] => "pseudonym",
490	            [0, 9, 2342, 19200300, 100, 1, 1] => "UID",
491	            [0, 9, 2342, 19200300, 100, 1, 25] => "DC",
492	            [1, 2, 840, 113549, 1, 9, 1] => "emailAddress",
493	            _ => return None,
494	        };
495	        Some(name)
496	    }
497	
498	    /// Decode a DirectoryString-style attribute value into UTF-8 text.
499	    fn decode_attribute_value(tag: u8, content: &[u8]) -> Result<String, String> {
500	        let s = match tag {
501	            0x0C => std::str::from_utf8(content)
502	                .map_err(|_| "invalid UTF-8 in UTF8String".to_string())?
503	                .to_string(),
504	            // ASCII-family strings: every byte is also its Unicode code point.
505	            0x12 | 0x13 | 0x16 | 0x1A => content.iter().map(|&b| b as char).collect(),
506	            // T.61 / GeneralString are conventionally treated as Latin-1 here.
507	            0x14 | 0x1B => content.iter().map(|&b| b as char).collect(),
508	            0x1E => {
509	                if content.len() % 2 != 0 {
510	                    return Err("odd-length BMPString".to_string());
511	                }
512	                let units: Vec<u16> = content
513	                    .chunks_exact(2)
514	                    .map(|c| u16::from_be_bytes([c[0], c[1]]))
515	                    .collect();
516	                char::decode_utf16(units.iter().copied())
517	                    .map(|r| r.map_err(|_| "unpaired surrogate in BMPString".to_string()))
518	                    .collect::<Result<String, _>>()?
519	            }
520	            0x1C => {
521	                if content.len() % 4 != 0 {
522	                    return Err("invalid UniversalString length".to_string());
523	                }
524	                let mut s = String::new();
525	                for c in content.chunks_exact(4) {
526	                    let cp = u32::from_be_bytes([c[0], c[1], c[2], c[3]]);
527	                    if (0xD800..=0xDFFF).contains(&cp) || cp > 0x10FFFF {
528	                        return Err("invalid code point in UniversalString".to_string());
529	                    }
530	                    s.push(char::from_u32(cp).unwrap());
531	                }
532	                s
533	            }
534	            _ => {
535	                return Err(format!(
536	                    "unsupported attribute value string type (tag 0x{tag:02X})"
537	                ))
538	            }
539	        };
540	        Ok(s)
541	    }
542	
543	    /// RFC 4514 value escaping; everything above the ASCII control range
544	    /// (including CJK text) passes through unchanged.
545	    fn escape_value(value: &str) -> String {
546	        let mut out = String::with_capacity(value.len());
547	        let last = value.chars().count().saturating_sub(1);
548	        for (i, c) in value.chars().enumerate() {
549	            let at_edge = i == 0 || i == last;
550	            let needs_backslash = matches!(c, ',' | '+' | '"' | '\\' | '<' | '>' | ';')
551	                || (at_edge && (c == ' ' || c == '#'));
552	            if needs_backslash {
553	                out.push('\\');
554	                out.push(c);
555	            } else if ('\0'..='\x1F').contains(&c) || c == '\x7F' {
556	                let mut buf = [0u8; 4];
557	                let b = c.encode_utf8(&mut buf).as_bytes()[0];
558	                write!(out, "\\{b:02X}").unwrap();
559	            } else {
560	                out.push(c);
561	            }
562	        }
563	        out
564	    }
565	
566	    fn format_time(tlv: Tlv) -> Result<String, String> {
567	        let (y, mo, d, h, mi, se) = match tlv.tag {
568	            TAG_UTC_TIME => {
569	                let c = tlv.content;
570	                if c.len() != 13 || c[12] != b'Z' {
571	                    return Err("UTCTime must be YYMMDDHHMMSSZ".to_string());
572	                }
573	                let digits = &c[..12];
574	                if !digits.iter().all(|b| b.is_ascii_digit()) {
575	                    return Err("non-numeric UTCTime".to_string());
576	                }
577	                let n = |a: usize, b: usize| -> u32 {
578	                    digits[a..=b].iter().fold(0, |acc, x| acc * 10 + (x - b'0') as u32)
579	                };
580	                let yy = n(0, 1);
581	                let year = if yy < 50 { 2000 + yy } else { 1900 + yy };
582	                (year as i32, n(2, 3), n(4, 5), n(6, 7), n(8, 9), n(10, 11))
583	            }
584	            TAG_GENERALIZED_TIME => {
585	                let c = tlv.content;
586	                if c.len() != 15 || c[14] != b'Z' {
587	                    return Err(
588	                        "GeneralizedTime must be YYYYMMDDHHMMSSZ in UTC".to_string()
589	                    );
590	                }
591	                let digits = &c[..14];
592	                if !digits.iter().all(|b| b.is_ascii_digit()) {
593	                    return Err("non-numeric GeneralizedTime".to_string());
594	                }
595	                let n = |a: usize, b: usize| -> u32 {
596	                    digits[a..=b].iter().fold(0, |acc, x| acc * 10 + (x - b'0') as u32)
597	                };
598	                (n(0, 3) as i32, n(4, 5), n(6, 7), n(8, 9), n(10, 11), n(12, 13))
599	            }
600	            other => return Err(format!("invalid time tag 0x{other:02X}")),
601	        };
602	        validate_datetime(y, mo, d, h, mi, se)?;
603	        Ok(format!("{y:04}-{mo:02}-{d:02}T{h:02}:{mi:02}:{se:02}Z"))
604	    }
605	
606	    fn validate_datetime(
607	        year: i32,
608	        month: u32,
609	        day: u32,
610	        hour: u32,
611	        minute: u32,
612	        second: u32,
613	    ) -> Result<(), String> {
614	        if !(1..=12).contains(&month) {
615	            return Err("invalid month in certificate time".to_string());
616	        }
617	        if hour > 23 || minute > 59 || second > 59 {
618	            return Err("invalid time of day in certificate time".to_string());
619	        }
620	        let leap = year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
621	        let days = [31, if leap { 29 } else { 28 }, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
622	        if day < 1 || day > days[(month - 1) as usize] {
623	            return Err("invalid day in certificate time".to_string());
624	        }
625	        Ok(())
626	    }
627	}
