1	//! End-to-end regression tests for the name (Subject/Issuer) decoding and
2	//! display behavior documented in README.md.
3	//!
4	//! These tests drive the real `chainview` binary so the public contract is
5	//! locked as a whole: the five output lines and their order on success, and
6	//! exit code 2 with empty stdout plus the `chainview: invalid DER
7	//! certificate:` stderr prefix on malformed input. Only name decoding is
8	//! exercised — signature verification, trust and expiry are intentionally out
9	//! of scope.
10	//!
11	//! Certificates are built with the tiny zero-dependency DER constructor at the
12	//! bottom of this file, which lets individual name components (including
13	//! truncated or non-minimal value encodings) be crafted byte for byte.
14	
15	use std::fs;
16	use std::path::PathBuf;
17	use std::process::{Command, Output};
18	use std::sync::atomic::{AtomicU64, Ordering};
19	
20	const FIXED_SERIAL: &str = "0E8A4C2F9B17D603";
21	const FIXED_NOT_BEFORE: &str = "2026-01-15T09:30:00Z";
22	const FIXED_NOT_AFTER: &str = "2027-01-15T09:30:00Z";
23	
24	// ----- Known X.520 attribute OID arcs -------------------------------------
25	
26	const CN: &[u64] = &[2, 5, 4, 3];
27	const O: &[u64] = &[2, 5, 4, 10];
28	const C: &[u64] = &[2, 5, 4, 6];
29	
30	// ----- Success cases -------------------------------------------------------
31	
32	#[test]
33	fn unknown_oid_uses_dotted_oid_and_full_der_hex() {
34	    // The exact README example: UTF8String "abc" for type 1.2.3.4 must render
35	    // as 1.2.3.4=#0C03616263 — tag, length and content, readable text or not.
36	    let subject = name(&[rdn(&[atv_utf8(&[1, 2, 3, 4], "abc")])]);
37	    let issuer = simple_cn_name("Test CA");
38	    let (out, _cert) = run_inspect("unknown-basic", &build_cert(&subject, &issuer));
39	
40	    assert_success(
41	        &out,
42	        "1.2.3.4=#0C03616263",
43	        "CN=Test CA",
44	    );
45	}
46	
47	#[test]
48	fn unknown_oid_value_preserves_long_form_length() {
49	    // A 128-byte content needs the long-form length 0x81 0x80; the hex must
50	    // carry the original TLV header verbatim instead of collapsing the length
51	    // or emitting only the content bytes.
52	    let long_text = "a".repeat(128);
53	    let subject = name(&[rdn(&[atv_utf8(&[1, 2, 3, 4], &long_text)])]);
54	    let issuer = simple_cn_name("Test CA");
55	    let (out, _cert) = run_inspect("unknown-longlen", &build_cert(&subject, &issuer));
56	
57	    let mut expected_hex = String::from("0C8180");
58	    expected_hex.push_str(&"61".repeat(128));
59	    assert_success(&out, &format!("1.2.3.4=#{expected_hex}"), "CN=Test CA");
60	}
61	
62	#[test]
63	fn unknown_oid_under_2_999_keeps_numeric_arcs() {
64	    // 2.999.* is a legal OID whose first subidentifier (1079) needs multiple
65	    // base-128 bytes (0x88 0x37); it must stay a dotted decimal identifier.
66	    let subject = name(&[rdn(&[atv_utf8(&[2, 999, 1], "x")])]);
67	    let issuer = simple_cn_name("Test CA");
68	    let (out, _cert) = run_inspect("unknown-2999", &build_cert(&subject, &issuer));
69	
70	    assert_success(&out, "2.999.1=#0C0178", "CN=Test CA");
71	}
72	
73	#[test]
74	fn unknown_non_string_value_is_shown_as_full_der_hex() {
75	    // An OCTET STRING value (tag 0x04) is not text at all; the full encoding
76	    // still appears after '#'.
77	    let value = tlv(0x04, &[0x01, 0x02, 0x03]);
78	    let subject = name(&[rdn(&[atv(&[1, 2, 3, 4], &value)])]);
79	    let issuer = simple_cn_name("Test CA");
80	    let (out, _cert) = run_inspect("unknown-octet", &build_cert(&subject, &issuer));
81	
82	    assert_success(&out, "1.2.3.4=#0403010203", "CN=Test CA");
83	}
84	
85	#[test]
86	fn mixed_known_and_unknown_attributes_keep_their_own_forms() {
87	    // Encoded RDN order (display is reversed):
88	    //   SET { C=CN }
89	    //   SET { O=示例公司 }
90	    //   SET { CN=example.com, 1.2.3.4 "abc", 1.2.3.4 "def" }
91	    // The last SET is one multi-valued RDN: joined with '+', never split into
92	    // groups; the repeated unknown attribute appears twice (never merged); the
93	    // adjacent CN stays text; CJK content passes through as raw UTF-8; groups
94	    // are shown in reverse order; '#' is the encoding marker, unescaped.
95	    let subject = name(&[
96	        rdn(&[atv_utf8(C, "CN")]),
97	        rdn(&[atv_utf8(O, "示例公司")]),
98	        rdn(&[
99	            atv_utf8(CN, "example.com"),
100	            atv_utf8(&[1, 2, 3, 4], "abc"),
101	            atv_utf8(&[1, 2, 3, 4], "def"),
102	        ]),
103	    ]);
104	    let issuer = simple_cn_name("Test CA");
105	    let (out, _cert) = run_inspect("mixed", &build_cert(&subject, &issuer));
106	
107	    assert_success(
108	        &out,
109	        "CN=example.com+1.2.3.4=#0C03616263+1.2.3.4=#0C03646566,O=示例公司,C=CN",
110	        "CN=Test CA",
111	    );
112	}
113	
114	#[test]
115	fn subject_and_issuer_render_independently() {
116	    // Each name reflects only its own attributes: distinct OID sets and value
117	    // encodings must never bleed across Subject/Issuer.
118	    let subject = name(&[
119	        rdn(&[atv_utf8(O, "测试")]),
120	        rdn(&[atv_utf8(CN, "subject.example")]),
121	    ]);
122	    let issuer = name(&[rdn(&[
123	        atv_utf8(CN, "Example CA"),
124	        atv_utf8(&[1, 2, 3, 4], "abc"),
125	    ])]);
126	    let (out, _cert) = run_inspect("separate-names", &build_cert(&subject, &issuer));
127	
128	    assert_success(
129	        &out,
130	        "CN=subject.example,O=测试",
131	        "CN=Example CA+1.2.3.4=#0C03616263",
132	    );
133	}
134	
135	#[test]
136	fn empty_subject_keeps_empty_field_while_issuer_shows() {
137	    // An empty SEQUENCE is a valid empty name: the Subject line stays empty
138	    // (just "Subject: ") while Issuer renders normally. All five fields keep
139	    // their documented order, and the time fields are UTC regardless of the
140	    // machine zone.
141	    let subject = tlv(0x30, &[]); // Name ::= SEQUENCE {}
142	    let issuer = simple_cn_name("Example CA");
143	    let (out, _cert) = run_inspect("empty-subject", &build_cert(&subject, &issuer));
144	
145	    assert_eq!(out.status.code(), Some(0), "stderr={}", lossy(&out.stderr));
146	    assert!(out.stderr.is_empty());
147	    assert_eq!(
148	        lossy(&out.stdout),
149	        format!(
150	            "Subject: \n\
151	             Issuer: CN=Example CA\n\
152	             Serial Number: {FIXED_SERIAL}\n\
153	             Not Before: {FIXED_NOT_BEFORE}\n\
154	             Not After: {FIXED_NOT_AFTER}\n"
155	        )
156	    );
157	}
158	
159	// ----- Failure cases -------------------------------------------------------
160	
161	#[test]
162	fn invalid_utf8_in_unknown_attribute_value_is_rejected() {
163	    // Tagged UTF8String but carrying 0xFF 0xFE: an input error even though the
164	    // value would have been shown as hex.
165	    let bad_value = tlv(0x0C, &[0xFF, 0xFE]);
166	    let subject = name(&[rdn(&[atv(&[1, 2, 3, 4], &bad_value)])]);
167	    let issuer = simple_cn_name("Test CA");
168	    let (out, _cert) = run_inspect("bad-utf8-unknown", &build_cert(&subject, &issuer));
169	
170	    assert_invalid_certificate(&out);
171	}
172	
173	#[test]
174	fn invalid_utf8_in_known_attribute_value_is_rejected() {
175	    // Same rule for a known short-name attribute: the value cannot be decoded.
176	    let bad_value = tlv(0x0C, &[0xFF]);
177	    let subject = name(&[rdn(&[atv(CN, &bad_value)])]);
178	    let issuer = simple_cn_name("Test CA");
179	    let (out, _cert) = run_inspect("bad-utf8-known", &build_cert(&subject, &issuer));
180	
181	    assert_invalid_certificate(&out);
182	}
183	
184	#[test]
185	fn truncated_attribute_value_is_rejected() {
186	    // The value header announces five content bytes but only three follow;
187	    // the enclosing SET/SEQUENCE lengths stay well-formed so truncation is
188	    // detected at the value itself.
189	    let mut inner = oid(&[1, 2, 3, 4]);
190	    inner.extend_from_slice(&[0x0C, 0x05, 0x61, 0x62, 0x63]); // len 5, 3 present
191	    let subject = name(&[rdn(&[seq(&inner)])]);
192	    let issuer = simple_cn_name("Test CA");
193	    let (out, _cert) = run_inspect("truncated-value", &build_cert(&subject, &issuer));
194	
195	    assert_invalid_certificate(&out);
196	}
197	
198	#[test]
199	fn non_minimal_value_length_encoding_is_rejected() {
200	    // A three-byte value encoded as 0x81 0x03 is not valid DER.
201	    let mut inner = oid(&[1, 2, 3, 4]);
202	    inner.extend_from_slice(&[0x0C, 0x81, 0x03, 0x61, 0x62, 0x63]);
203	    let subject = name(&[rdn(&[seq(&inner)])]);
204	    let issuer = simple_cn_name("Test CA");
205	    let (out, _cert) = run_inspect("nonminimal-len", &build_cert(&subject, &issuer));
206	
207	    assert_invalid_certificate(&out);
208	}
209	
210	#[test]
211	fn truncated_certificate_file_is_rejected() {
212	    // Bytes cut off the tail of an otherwise valid certificate: malformed
213	    // input, same failure contract.
214	    let subject = simple_cn_name("subject.example");
215	    let issuer = simple_cn_name("Test CA");
216	    let mut bytes = build_cert(&subject, &issuer);
217	    bytes.truncate(bytes.len() - 5);
218	    let (out, _cert) = run_inspect("truncated-cert", &bytes);
219	
220	    assert_invalid_certificate(&out);
221	}
222	
223	// ----- CLI contract: usage, version and unreadable files ------------------
224	
225	#[test]
226	fn version_flag_keeps_its_output() {
227	    let out = Command::new(env!("CARGO_BIN_EXE_chainview"))
228	        .arg("--version")
229	        .output()
230	        .expect("running chainview");
231	    assert_eq!(out.status.code(), Some(0));
232	    assert!(out.stderr.is_empty());
233	    assert_eq!(lossy(&out.stdout), "chainview 0.1.0\n");
234	}
235	
236	#[test]
237	fn missing_path_is_a_usage_error() {
238	    let out = Command::new(env!("CARGO_BIN_EXE_chainview"))
239	        .arg("inspect")
240	        .output()
241	        .expect("running chainview");
242	    assert_eq!(out.status.code(), Some(2));
243	    assert!(out.stdout.is_empty());
244	    assert_eq!(
245	        lossy(&out.stderr),
246	        "Usage: chainview inspect <DER-FILE>\n       chainview --version\n"
247	    );
248	}
249	
250	#[test]
251	fn unreadable_file_keeps_its_error_contract() {
252	    let missing = std::env::temp_dir().join("chainview-name-test-definitely-missing.der");
253	    let _ = fs::remove_file(&missing);
254	    let out = Command::new(env!("CARGO_BIN_EXE_chainview"))
255	        .arg("inspect")
256	        .arg(&missing)
257	        .output()
258	        .expect("running chainview");
259	    assert_eq!(out.status.code(), Some(2));
260	    assert!(out.stdout.is_empty());
261	    let stderr = lossy(&out.stderr);
262	    assert!(
263	        stderr.starts_with(&format!(
264	            "chainview: cannot read certificate file '{}': ",
265	            missing.display()
266	        )),
267	        "unexpected stderr: {stderr}"
268	    );
269	}
270	
271	// ----- Assertions / process plumbing --------------------------------------
272	
273	fn assert_success(out: &Output, subject: &str, issuer: &str) {
274	    assert_eq!(out.status.code(), Some(0), "stderr={}", lossy(&out.stderr));
275	    assert!(out.stderr.is_empty(), "stderr={}", lossy(&out.stderr));
276	    assert_eq!(
277	        lossy(&out.stdout),
278	        format!(
279	            "Subject: {subject}\n\
280	             Issuer: {issuer}\n\
281	             Serial Number: {FIXED_SERIAL}\n\
282	             Not Before: {FIXED_NOT_BEFORE}\n\
283	             Not After: {FIXED_NOT_AFTER}\n"
284	        )
285	    );
286	}
287	
288	/// Every malformed-input case shares the documented contract: exit code 2,
289	/// nothing on stdout (so no name field can be printed before the error is
290	/// noticed), and the fixed invalid-certificate message prefix on stderr.
291	fn assert_invalid_certificate(out: &Output) {
292	    assert_eq!(
293	        out.status.code(),
294	        Some(2),
295	        "stdout={} stderr={}",
296	        lossy(&out.stdout),
297	        lossy(&out.stderr)
298	    );
299	    assert!(
300	        out.stdout.is_empty(),
301	        "stdout must be empty on failure, got: {}",
302	        lossy(&out.stdout)
303	    );
304	    let stderr = lossy(&out.stderr);
305	    assert!(
306	        stderr.starts_with("chainview: invalid DER certificate: "),
307	        "unexpected stderr: {stderr}"
308	    );
309	    // A non-empty reason after the fixed prefix.
310	    assert!(
311	        stderr["chainview: invalid DER certificate: ".len()..].trim().len() > 1,
312	        "missing error reason in stderr: {stderr}"
313	    );
314	}
315	
316	fn lossy(bytes: &[u8]) -> String {
317	    String::from_utf8_lossy(bytes).into_owned()
318	}
319	
320	fn run_inspect(tag: &str, data: &[u8]) -> (Output, TempCert) {
321	    let cert = TempCert::new(tag, data);
322	    let output = Command::new(env!("CARGO_BIN_EXE_chainview"))
323	        .arg("inspect")
324	        .arg(&cert.path)
325	        .output()
326	        .expect("running chainview");
327	    (output, cert)
328	}
329	
330	struct TempCert {
331	    path: PathBuf,
332	}
333	
334	impl TempCert {
335	    fn new(tag: &str, data: &[u8]) -> Self {
336	        static COUNTER: AtomicU64 = AtomicU64::new(0);
337	        let unique = COUNTER.fetch_add(1, Ordering::Relaxed);
338	        let path = std::env::temp_dir().join(format!(
339	            "chainview-name-test-{}-{tag}-{unique}.der",
340	            std::process::id()
341	        ));
342	        fs::write(&path, data).expect("writing temp certificate");
343	        TempCert { path }
344	    }
345	}
346	
347	impl Drop for TempCert {
348	    fn drop(&mut self) {
349	        let _ = fs::remove_file(&self.path);
350	    }
351	}
352	
353	// ----- Certificate / DER construction -------------------------------------
354	//
355	// Only the structural pieces needed here. Lengths are always emitted in the
356	// minimal DER form, except where a test injects raw bytes to exercise
357	// rejection of non-minimal or truncated encodings.
358	
359	fn simple_cn_name(cn: &str) -> Vec<u8> {
360	    name(&[rdn(&[atv_utf8(CN, cn)])])
361	}
362	
363	/// Assemble a complete, parseable v1 DER certificate with fixed serial,
364	/// validity and key material around the supplied Subject/Issuer names.
365	fn build_cert(subject: &[u8], issuer: &[u8]) -> Vec<u8> {
366	    let serial = tlv(0x02, &[0x0E, 0x8A, 0x4C, 0x2F, 0x9B, 0x17, 0xD6, 0x03]);
367	    let validity = seq(&concat(&[
368	        &tlv(0x17, b"260115093000Z"), // UTCTime 2026-01-15T09:30:00Z
369	        &tlv(0x17, b"270115093000Z"), // UTCTime 2027-01-15T09:30:00Z
370	    ]));
371	    let spki = seq(&concat(&[
372	        &seq(&concat(&[&oid(&[1, 2, 840, 113549, 1, 1, 1]), &tlv(0x05, &[])])),
373	        &tlv(0x03, &[0x00, 0x01, 0x00]), // BIT STRING, zero unused bits
374	    ]));
375	
376	    let tbs = seq(&concat(&[
377	        &serial,
378	        &signature_algorithm(),
379	        issuer,
380	        &validity,
381	        subject,
382	        &spki,
383	    ]));
384	    seq(&concat(&[&tbs, &signature_algorithm(), &tlv(0x03, &[0x00])]))
385	}
386	
387	fn signature_algorithm() -> Vec<u8> {
388	    // sha256WithRSAEncryption with explicit NULL parameters.
389	    seq(&concat(&[&oid(&[1, 2, 840, 113549, 1, 1, 11]), &tlv(0x05, &[])]))
390	}
391	
392	fn name(rdns: &[Vec<u8>]) -> Vec<u8> {
393	    tlv(
394	        0x30,
395	        &concat(&rdns.iter().map(Vec::as_slice).collect::<Vec<_>>()),
396	    )
397	}
398	
399	fn rdn(atvs: &[Vec<u8>]) -> Vec<u8> {
400	    tlv(
401	        0x31,
402	        &concat(&atvs.iter().map(Vec::as_slice).collect::<Vec<_>>()),
403	    )
404	}
405	
406	/// AttributeTypeAndValue ::= SEQUENCE { type OID, value ANY } — `value` is the
407	/// complete DER TLV of the value.
408	fn atv(arcs: &[u64], value: &[u8]) -> Vec<u8> {
409	    seq(&concat(&[&oid(arcs), value]))
410	}
411	
412	fn atv_utf8(arcs: &[u64], text: &str) -> Vec<u8> {
413	    atv(arcs, &tlv(0x0C, text.as_bytes()))
414	}
415	
416	fn oid(arcs: &[u64]) -> Vec<u8> {
417	    assert!(arcs.len() >= 2);
418	    let mut content = oid_arc(arcs[0] * 40 + arcs[1]);
419	    for &arc in &arcs[2..] {
420	        content.extend_from_slice(&oid_arc(arc));
421	    }
422	    tlv(0x06, &content)
423	}
424	
425	fn oid_arc(mut value: u64) -> Vec<u8> {
426	    let mut out = vec![(value % 128) as u8];
427	    value /= 128;
428	    while value > 0 {
429	        out.push(0x80 | (value % 128) as u8);
430	        value /= 128;
431	    }
432	    out.reverse();
433	    out
434	}
435	
436	fn seq(content: &[u8]) -> Vec<u8> {
437	    tlv(0x30, content)
438	}
439	
440	fn tlv(tag: u8, content: &[u8]) -> Vec<u8> {
441	    let mut out = vec![tag];
442	    out.extend_from_slice(&der_len(content.len()));
443	    out.extend_from_slice(content);
444	    out
445	}
446	
447	fn der_len(n: usize) -> Vec<u8> {
448	    if n < 0x80 {
449	        vec![n as u8]
450	    } else {
451	        let mut body = Vec::new();
452	        let mut v = n;
453	        while v > 0 {
454	            body.push((v & 0xFF) as u8);
455	            v >>= 8;
456	        }
457	        body.reverse();
458	        let mut out = vec![0x80 | body.len() as u8];
459	        out.extend_from_slice(&body);
460	        out
461	    }
462	}
463	
464	fn concat(parts: &[&[u8]]) -> Vec<u8> {
465	    let mut out = Vec::new();
466	    for part in parts {
467	        out.extend_from_slice(part);
468	    }
469	    out
470	}
471

